package com.hbm.machine.reactor.rbmk.fuel;
import java.util.List;import com.hbm.entity.effect.EntityQuasar;import com.hbm.exposure.HbmExposure;import com.hbm.registry.HbmContent;import net.minecraft.ChatFormatting;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.Entity;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;
/** True source ItemDigamma(60), including flat stack-per-tick exposure and the actual quasar drop. */
public final class DigammaParticleItem extends Item {
 public final int digamma;public DigammaParticleItem(int ticks){super(new Properties());digamma=ticks;}@Override public void inventoryTick(ItemStack stack,Level level,Entity holder,int slot,boolean selected){super.inventoryTick(stack,level,holder,slot,selected);if(!level.isClientSide&&holder instanceof Player player)HbmExposure.applyDigammaData(player,1F/digamma);}
 @Override public boolean hasCraftingRemainingItem(ItemStack stack){return true;}@Override public ItemStack getCraftingRemainingItem(ItemStack stack){return new ItemStack(HbmContent.item("particle_empty"));}
 @Override public void appendHoverText(ItemStack stack,TooltipContext context,List<Component> lines,TooltipFlag flag){lines.add(Component.translatable("trait.hlParticle","1.67*10³⁴a").withStyle(ChatFormatting.GOLD));lines.add(Component.translatable("trait.hlPlayer",digamma/20F+"s").withStyle(ChatFormatting.RED));lines.add(Component.empty());float dose=((int)((1000F/digamma)*200F))/10F;lines.add(Component.literal("[").append(Component.translatable("trait.digamma")).append("]").withStyle(ChatFormatting.RED));lines.add(Component.literal(dose+"mDRX/s").withStyle(ChatFormatting.DARK_RED));lines.add(Component.literal("[").append(Component.translatable("trait.drop")).append("]").withStyle(ChatFormatting.RED));}
 @Override public boolean onEntityItemUpdate(ItemStack stack,ItemEntity entity){if(entity.onGround()&&!entity.level().isClientSide){if(ParticleConfig.droppedSingularities()){var quasar=new EntityQuasar(entity.level(),5F);quasar.setPos(entity.position());entity.level().addFreshEntity(quasar);}entity.discard();return true;}return false;}
}
